#!/usr/bin/env bash
# Compiles kubeport-ffi, generates the Swift bindings and assembles app/KubeportFFI.xcframework.
# Outputs (ignored by git):
#   app/KubeportFFI.xcframework           static library + headers + modulemap
#   app/Sources/Kubeport/Generated/       Swift code generated by UniFFI
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
GEN="$ROOT/target/uniffi"
XCF="$ROOT/app/KubeportFFI.xcframework"
SWIFT_OUT="$ROOT/app/Sources/Kubeport/Generated"

cd "$ROOT"
cargo build --release --locked -p kubeport-ffi

rm -rf "$GEN" "$XCF" "$SWIFT_OUT"
mkdir -p "$GEN/include" "$SWIFT_OUT"
cargo run --release --locked -q -p kubeport-ffi --bin uniffi-bindgen -- \
  target/release/libkubeport_ffi.dylib "$GEN" \
  --swift-sources --headers --modulemap \
  --module-name kubeport_ffiFFI --modulemap-filename module.modulemap

mv "$GEN"/*.h "$GEN/module.modulemap" "$GEN/include/"
mv "$GEN"/*.swift "$SWIFT_OUT/"

xcodebuild -create-xcframework \
  -library target/release/libkubeport_ffi.a \
  -headers "$GEN/include" \
  -output "$XCF" >/dev/null
echo "$XCF"
